import React from 'react';
import { NavLink } from 'react-router-dom';

const Sidebar = () => {
  const activeStyle = {
    backgroundColor: '#EFF6FF', // A light blue background
    color: '#3B82F6', // The primary blue color
  };

  return (
    <aside className="w-64 bg-card-light dark:bg-card-dark flex-col hidden lg:flex shadow-lg">
      <div className="p-6 flex items-center space-x-3">
        <div className="w-8 h-8 bg-blue-500 rounded-full flex-shrink-0"></div>
        <h1 className="text-xl font-bold text-text-light dark:text-text-dark">University HRMS</h1>
      </div>
      <nav className="flex-1 px-4 py-2 space-y-2">
        <NavLink 
          to="/dashboard" 
          className="flex items-center px-4 py-2 text-sm font-medium text-subtext-light dark:text-subtext-dark rounded-lg hover:bg-gray-100 dark:hover:bg-gray-700"
          style={({ isActive }) => isActive ? activeStyle : undefined}
        >
          <span className="material-icons mr-3">dashboard</span> Admin Dashboard
        </NavLink>
        <NavLink 
          to="/employees" 
          className="flex items-center px-4 py-2 text-sm font-medium text-subtext-light dark:text-subtext-dark rounded-lg hover:bg-gray-100 dark:hover:bg-gray-700"
          style={({ isActive }) => isActive ? activeStyle : undefined}
        >
          <span className="material-icons mr-3">people</span> Staff Directory
        </NavLink>
        <NavLink 
          to="/add-employee" 
          className="flex items-center px-4 py-2 text-sm font-medium text-subtext-light dark:text-subtext-dark rounded-lg hover:bg-gray-100 dark:hover:bg-gray-700"
          style={({ isActive }) => isActive ? activeStyle : undefined}
        >
          <span className="material-icons mr-3">person_add</span> Add New Staff
        </NavLink>
      </nav>
    </aside>
  );
};

export default Sidebar;
